def parse_duration(text: str) -> int:
    if not text:
        raise ValueError("Empty string provided")

    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    parts = text.split()

    if len(parts) != 1 and len(parts) != 3:
        raise ValueError("Invalid number of parts")

    if len(parts) == 1:
        if parts[0].isdigit():
            return int(parts[0])
        else:
            raise ValueError("Number without a unit")

    numbers = []
    units_list = []

    for part in parts:
        if part.isdigit():
            numbers.append(int(part))
        elif part in units:
            units_list.append(part)
        else:
            raise ValueError("Unknown unit")

    if len(numbers) != len(units_list):
        raise ValueError("Repeated unit")

    total_seconds = 0
    for number, unit in zip(numbers, units_list):
        total_seconds += number * units[unit]

    return total_seconds
